"""Round 5-6: architecture, interiors, landscapes (scene_*), activity and interaction poses (pose_activity_*, pose_interact_*). Descriptions only."""
import os, re, sys, random, zlib
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
from paths import FINAL
def S(x): return [i.strip() for i in x.split(';') if i.strip()]
def R(*k): return random.Random(zlib.crc32('|'.join(map(str, k)).encode()))
ARCH = S("a Japanese wooden temple with curved eaves; a Gothic cathedral with flying buttresses; a Roman amphitheatre; a Greek temple with fluted columns; a Mughal palace with domes and arches; a Moorish courtyard with tiled fountains; a Mesoamerican stepped pyramid; a Khmer stone temple covered in roots; a Persian mosque with blue tiled domes; an Ethiopian rock-hewn church; a West African mud-brick mosque with projecting beams; a Yemeni tower house in mud brick; a Venetian palazzo on a canal; a Georgian terrace with sash windows; a Victorian townhouse with bay windows; an Art Deco skyscraper; a Bauhaus block; a brutalist concrete tower; a mid-century modern house with a flat roof; a glass modernist pavilion; a Scandinavian timber cabin; an alpine chalet with carved balconies; a Cape Dutch farmhouse; a Spanish colonial mission; a Pueblo adobe village; an igloo; a Mongolian ger; a Bedouin tent; a stilt house over water; a Dogon cliff village; a Cappadocian cave dwelling; a Chinese courtyard house; a pagoda; a Thai gilded temple; a Balinese gateway; a Korean hanok; a Tibetan monastery on a cliff; a Russian onion-domed church; a medieval castle on a hill; a half-timbered Tudor house; a windmill; a lighthouse; a clock tower; a covered bridge; a suspension bridge; a Roman aqueduct; a railway station with iron roof; a market hall; a modern glass-walled library; a futuristic spiral tower; a floating village; a treehouse village; a shipping-container home; a prefab tiny home; an earthship; a bamboo pavilion")
STYLE = S("at sunrise; at midday; at golden hour; at dusk; at night under lights; in fog; in rain; under heavy snow; in autumn colour; in spring blossom; covered in ivy; ruined and overgrown; freshly restored; busy with crowds; completely empty; during a festival with lanterns; seen from a low angle; seen from far away across a valley; reflected in water; with scaffolding")
ROOMS = S("a cramped studio flat; a sunlit loft; a grand library with ladders; a farmhouse kitchen; a minimalist white kitchen; a tiny galley kitchen; a dim bar; a bright cafe; a teahouse with floor cushions; a bookshop with towering shelves; a tailor's workshop; a barber's shop; a potter's studio; a recording studio; a dance studio with mirrors; a gym with weights; a spa with steam; a communal bathhouse; a hot spring; a bathroom with a clawfoot tub; a cosy bedroom with quilts; a modern bedroom with a low platform bed; a hospital room; a dental office; a tiered lecture hall; a laboratory; a server room; a cockpit; a ship's cabin; a train sleeper compartment; a caravan interior; a cathedral nave; a mosque prayer hall; a temple courtyard; a throne room; a ballroom with chandeliers; a speakeasy; a diner with booths; a night market stall; a rooftop terrace; a greenhouse; an attic full of old trunks; a cellar with wine racks; a garage workshop; a cluttered artist's studio; an antique shop; a theatre backstage; a circus tent interior; a sauna; a yurt; a hut with a fire pit")
ROOMLOOK = S("lit by candles; lit by a window; lit by neon; lit by fluorescent tubes; lit by a single lamp; in warm evening light; in cool morning light; cluttered and lived-in; tidy and sparse; with plants everywhere; with patterned wallpaper; with exposed brick; with wood panelling; with a vaulted ceiling; with a low ceiling; with stained glass; with mirrors on every wall; with rugs layered on the floor")
LAND = S("a desert of rippling dunes; a salt flat mirror; a red rock canyon; a cold desert plateau; a savanna with lone acacias; a tropical rainforest; a cloud forest; a bamboo forest; a temperate autumn forest; a pine forest in snow; a mangrove swamp; a bayou with cypress; a peat bog; a wildflower meadow; a rolling farmland; a terraced rice field; a vineyard hillside; a lavender field; a tundra; a glacier; an ice cave; an iceberg-filled bay; a fjord; a volcano with a lava flow; a geyser basin; a hot-spring terrace; a limestone karst river; a stone forest; a cenote; a coral atoll; a white-sand beach; a rocky shore with tide pools; a sea cliff; a sea stack; a black-sand beach; a mountain ridge; an alpine lake; a waterfall; a gorge; a cave with stalactites; a slot canyon; a badlands; an oasis; a river delta; a steppe; a moor; a highland loch; a lava tube; a steaming crater lake; a floating market river; a mountain pass")
LANDW = S("at dawn; at midday; at golden hour; at twilight; under a full moon; under the milky way; during a storm; in thick mist; after rain with rainbows; under aurora lights; in a heat shimmer; in a dust storm; under a clear sky; in falling snow; in autumn; in spring bloom")
ACT = S("stretching on a mat; running on a path; hiking a trail; climbing a rock face; swimming laps; paddling a kayak; cycling; skating; dancing alone; practising martial arts forms; lifting weights; doing yoga; playing an instrument; painting at an easel; cooking at a stove; baking and kneading dough; gardening on knees; repairing a bike; typing at a desk; reading in a chair; knitting; sewing at a machine; carving wood; pottery on a wheel; playing a board game; playing guitar around a fire; fishing from a boat; fixing a roof; carrying groceries; walking a dog; pushing a wheelchair uphill; using crutches; using a white cane; signing in sign language; laughing with head thrown back; sleeping in a hammock; sunbathing; floating in water; skiing downhill; surfing a wave; sailing; riding a horse; skating a half-pipe; juggling; performing a magic trick; busking on a street; presenting at a podium")
INT = S("two people sharing a laugh; two people dancing together; two people hugging; two people in a tight embrace; two people holding hands while walking; two people sitting back to back; two people leaning on each other; two people sharing an umbrella; two people studying a map together; two people cooking together; two people practising a sport together; two people sparring in a friendly match; two people playing a duet; a person helping another to stand; a person tying another's tie; a person fixing another's collar; a person braiding another's hair; a person applying another's makeup; a person adjusting another's costume; a person feeding another; a person carrying another on their back; a person lifting another in a dance lift; a person whispering in another's ear; a person resting their head on another's shoulder; a person kissing another on the cheek; two people kissing; a group huddle; a group photo pose; a group sitting around a table; a group dancing in a circle; a group in a conga line; a group playing a team game; a group around a campfire; a group passing a ball; a person measuring another for a fitting; a person helping another into a harness; a person helping another into an armour piece; a person helping another with a zip; a person wrapping a scarf around another; a person lacing another's corset; a person guiding another by the hand; a person pushing another on a swing; a pair of dancers in a tango frame; a pair in a waltz hold; a pair in a mirror pose; a pair in a trust fall")
def mk():
    G = {}
    G['scene_arch'] = sorted({f"{a}, {s}" for a in ARCH for s in STYLE if R('a', a, s).random() < .3}); G['scene_arch_building'] = ARCH; G['scene_arch_light'] = STYLE
    G['scene_room'] = sorted({f"{a}, {s}" for a in ROOMS for s in ROOMLOOK if R('r', a, s).random() < .3}); G['scene_room_type'] = ROOMS; G['scene_room_look'] = ROOMLOOK
    G['scene_landscape'] = sorted({f"{a}, {s}" for a in LAND for s in LANDW if R('l', a, s).random() < .3}); G['scene_landscape_type'] = LAND; G['scene_landscape_light'] = LANDW
    G['pose_activity'] = ACT; G['pose_interact'] = INT
    G['scene_prompt'] = ['__scene_arch__.', '__scene_room__.', '__scene_landscape__.', 'A person __pose_activity__ in __scene_room_type__.', 'A person __pose_activity__ in __scene_landscape__.', '__pose_interact__ in __scene_room_type__.']
    return G
def build(): return mk()
def run(final):
    G = build()
    for n, l in G.items():
        assert l and all(l), n
        open(os.path.join(final, n + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(dict.fromkeys(l)) + '\n')
    print('places/poses:', len(G), 'files'); return G
def export_aoo(out, prefix='aoo_'):
    G = build(); names_ = set(G); ref = re.compile(r'__([A-Za-z0-9_\-/]+)__'); n = 0
    for name, lines in G.items():
        keep = list(dict.fromkeys(ref.sub(lambda m: '__' + prefix + m.group(1) + '__' if m.group(1) in names_ else m.group(0), l) for l in lines))
        if name != 'scene_prompt': random.Random(zlib.crc32(name.encode())).shuffle(keep)
        open(os.path.join(out, prefix + name + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(keep) + '\n'); n += 1
    return n
if __name__ == '__main__':
    a = [x for x in sys.argv[1:] if os.path.isdir(x)]; run(os.path.abspath(a[0]) if a else FINAL)
